From 76bcb8b4077e6c2d02928bc3d1f9a9740911cc55 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 19 Nov 2026 16:49:10 +0100
Subject: [PATCH] containments/desktop: Don't drag icons when using the
 scrollbar

Dragging or clicking the desktop scrollbar over an icon also moved or
selected that icon, because the scrollbars sat inside the area handling
icon clicks; they now sit on top of it, so they only scroll the view.

BUG: 518558
---
 .../package/contents/ui/FolderView.qml        | 33 ++++++++++++-------
 1 file changed, 21 insertions(+), 12 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..266db59bff 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -52,7 +52,7 @@ FocusScope {
     property alias scrollUp: gridView.scrollUp
     property alias scrollDown: gridView.scrollDown
     property alias hoveredItem: gridView.hoveredItem
-    property alias containsMouse: listener.containsMouse
+    readonly property bool containsMouse: listener.containsMouse || verticalScrollBar.hovered || horizontalScrollBar.hovered
     property var history: []
     property var lastPosition: null
     property bool goingBack: false
@@ -232,11 +232,6 @@ FocusScope {

         onPressed: mouse => {

-            // Ignore press events outside the viewport (i.e. on scrollbars).
-            if (!scrollArea.viewport.contains(Qt.point(mouse.x, mouse.y))) {
-                return;
-            }
-
             // Ignore clicks if main.editor is enabled and we click on that
             // BUG:494558
             if (main.editor && childAt(mouse.x, mouse.y) === main.editor) {
@@ -702,12 +697,8 @@ FocusScope {
                     return -1
                 }

-                PlasmaComponents.ScrollBar.vertical: PlasmaComponents.ScrollBar {
-                    id: verticalScrollBar
-                }
-                PlasmaComponents.ScrollBar.horizontal: PlasmaComponents.ScrollBar {
-                    id: horizontalScrollBar
-                }
+                PlasmaComponents.ScrollBar.vertical: verticalScrollBar
+                PlasmaComponents.ScrollBar.horizontal: horizontalScrollBar

                 function calcExtraSpacing(cellSize, containerSize) {
                     const availableColumns = Math.floor(containerSize / cellSize);
@@ -1397,4 +1388,22 @@ FocusScope {
             }
         }
     }
+
+    PlasmaComponents.ScrollBar {
+        id: verticalScrollBar
+        anchors {
+            top: listener.top
+            bottom: listener.bottom
+            right: listener.right
+        }
+    }
+
+    PlasmaComponents.ScrollBar {
+        id: horizontalScrollBar
+        anchors {
+            left: listener.left
+            right: listener.right
+            bottom: listener.bottom
+        }
+    }
 }
-- 
